// Получаем данные из предыдущей ноды get_users
const usersRaw = $input.first().json.data;

// Если данных нет, возвращаем пустой массив
if (!usersRaw) return [];

// Worksection отдает объект, превращаем его в массив
const users = Object.values(usersRaw);

// 1. Извлекаем ПОЛЕ "department" из каждого юзера
