const data = $input.first().json.data;
const batchOffsetData = $('Get Batch Offset').first().json;
const currentOffset = batchOffsetData.batch_offset || 0;
const BATCH_SIZE = 50;

if (!data) return [{ _done: true, message: 'No projects data' }];

const allProjects = Object.values(data);

// 90 днів тому
const cutoffDate = new Date();
cutoffDate.setDate(cutoffDate.getDate() - 90);

// Фільтруємо проекти
const filteredProjects = allProjects.filter(p => {
  if (p.status === 'active') return true;
  if (p.status === 'pending') return true;

  if (p.status === 'done' || p.status === 'archive') {
    if (p.date_closed) {
      const dateClosed = new Date(p.date_closed);
      return dateClosed >= cutoffDate;
    }
    return false;
  }
  return false;
});

// Сортуємо для консистентності
filteredProjects.sort((a, b) => Number(a.id) - Number(b.id));

const totalProjects = filteredProjects.length;

// Перевіряємо чи є ще проекти для обробки
if (currentOffset >= totalProjects) {
  // Всі проекти оброблені — скидаємо offset на 0
  return [{ 
    _reset: true, 
    _done: true,
    message: 'All projects processed, resetting offset',
    totalProjects,
    currentOffset
  }];
}

// Вибираємо batch
const batchProjects = filteredProjects.slice(currentOffset, currentOffset + BATCH_SIZE);
const nextOffset = currentOffset + BATCH_SIZE;
const isLastBatch = nextOffset >= totalProjects;

// Дати для costs (90 днів)
const today = new Date();
const startDate = new Date();
startDate.setDate(today.getDate() - 90);

const formatDate = (d) => {
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return day + '.' + month + '.' + year;
};

const datestart = formatDate(startDate);
const dateend = formatDate(today);

// Логування
console.log('=== BATCH INFO ===');
console.log('Total filtered projects: ' + totalProjects);
console.log('Current offset: ' + currentOffset);
console.log('Batch size: ' + batchProjects.length);
console.log('Next offset: ' + nextOffset);
console.log('Is last batch: ' + isLastBatch);

// Повертаємо проекти з метаданими
const result = batchProjects.map((p, index) => ({
  id: p.id,
  name: p.name,
  status: p.status,
  datestart,
  dateend,
  _batchIndex: index,
  _nextOffset: nextOffset,
  _isLastBatch: isLastBatch,
  _totalProjects: totalProjects
}));

return result;

