const loopData = $('Loop Projects3').first().json;
const projectId = loopData.id;
const rawData = $input.first().json.data;
const validUsersRaw = $('Get Valid Users4').all();
const validUserIds = new Set(validUsersRaw.map(item => Number(item.json.id)));

const datestart = loopData.datestart;
const dateend = loopData.dateend;
const nextOffset = loopData._nextOffset;
const isLastBatch = loopData._isLastBatch;

// ✅ ФУНКЦИЯ для исправления кодировки UTF-8
function fixEncoding(str) {
    if (!str || typeof str !== 'string') return str;

    try {
        // Проверяем, есть ли некорректные символы (китайские иероглифы вместо кириллицы)
        // Если строка выглядит нормально, не трогаем её
        const hasBadChars = /[\u4E00-\u9FFF\u3400-\u4DBF]/.test(str);
        if (!hasBadChars) {
            return str;
        }

        // Пробуем исправить double-encoded UTF-8
        // Конвертируем строку обратно в байты
        const bytes = [];
        for (let i = 0; i < str.length; i++) {
            const code = str.charCodeAt(i);
            if (code <= 0xFF) {
                bytes.push(code);
            } else {
                // Если символы уже вне latin1 диапазона, возвращаем оригинал
                return str;
            }
        }

        // Декодируем байты как UTF-8
        const uint8Array = new Uint8Array(bytes);
        const decoder = new TextDecoder('utf-8');
        const decoded = decoder.decode(uint8Array);

        // Проверяем, улучшилось ли
        const stillBad = /[\u4E00-\u9FFF\u3400-\u4DBF]/.test(decoded);
        if (stillBad) {
            return str; // Не помогло, возвращаем оригинал
        }

        return decoded;
    } catch (e) {
        // В случае ошибки возвращаем оригинал
        return str;
    }
}

if ($input.first().json.error || !rawData || Object.keys(rawData).length === 0) {
    return [{ _empty: true, _projectId: projectId, datestart, dateend, _nextOffset: nextOffset, _isLastBatch: isLastBatch }];
}

const cutoffDate = new Date();
cutoffDate.setDate(cutoffDate.getDate() - 90);

let taskCount = 0;
const MAX_TASKS = 5000;
const MAX_DEPTH = 10;

function flattenTasks(tasksObj, parentId, depth = 0) {
    let result = [];
    if (depth > MAX_DEPTH) return result;

    const tasks = Object.values(tasksObj);
    for (let i = 0; i < tasks.length; i++) {
        if (taskCount >= MAX_TASKS) return result;
        const task = tasks[i];

        try {
            const dateClosed = task.date_closed ? new Date(task.date_closed) : null;
            const isActive = task.status === 'active';
            const isRecentClosed = task.status === 'done' && dateClosed && dateClosed >= cutoffDate;

            if (!isActive && !isRecentClosed) {
                const children = task.subtasks || task.child;
                if (children && typeof children === 'object') {
                    result = result.concat(flattenTasks(children, Number(task.id), depth + 1));
                }
                continue;
            }

            let userFromId = task.user_from?.id ? Number(task.user_from.id) : null;
            let userToId = task.user_to?.id ? Number(task.user_to.id) : null;

            if (userFromId === 0 || (userFromId && !validUserIds.has(userFromId))) userFromId = 7;
            if (userToId === 0 || (userToId && !validUserIds.has(userToId))) userToId = 7;

            taskCount++;

            // ✅ Применяем fixEncoding к name и text
            const taskName = task.name ? fixEncoding(task.name.substring(0, 500)) : '';
            const taskText = task.text ? fixEncoding(task.text.substring(0, 10000)) : null;

            result.push({
                id: Number(task.id),
                project_id: projectId,
                parent_id: parentId,
                name: taskName,
                text: taskText,
                status: task.status || null,
                priority: task.priority ? Number(task.priority) : 0,
                page: task.page || null,
                date_added: task.date_added || null,
                date_start: task.date_start || null,
                date_end: task.date_end || null,
                date_closed: task.date_closed || null,
                user_from_id: userFromId,
                user_to_id: userToId,
                tags: task.tags || null,
                datestart,
                dateend,
                _nextOffset: nextOffset,
                _isLastBatch: isLastBatch
            });

            const children = task.subtasks || task.child;
            if (children && typeof children === 'object') {
                result = result.concat(flattenTasks(children, Number(task.id), depth + 1));
            }
        } catch (e) {
            // Skip invalid tasks
            console.error('Error processing task:', e);
        }
    }
    return result;
}

const tasks = flattenTasks(rawData, null, 0);
if (tasks.length === 0) return [{ _empty: true, _projectId: projectId, datestart, dateend, _nextOffset: nextOffset, _isLastBatch: isLastBatch }];
return tasks;

const loopData = $('Loop Projects3').first().json;
const projectId = loopData.id;
const rawData = $input.first().json.data;
const validUsersRaw = $('Get Valid Users4').all();
const validUserIds = new Set(validUsersRaw.map(item => Number(item.json.id)));

const nextOffset = loopData._nextOffset;
const isLastBatch = loopData._isLastBatch;

let validTaskIds = new Set();
try {
    const flattenedTasks = $('Flatten Tasks4').all();
    for (const item of flattenedTasks) {
        if (item.json.id) validTaskIds.add(Number(item.json.id));
    }
} catch (e) {}

if ($input.first().json.status === 'error' || $input.first().json.error || !rawData || Object.keys(rawData).length === 0) {
  return [{ _empty: true, _projectId: projectId, _nextOffset: nextOffset, _isLastBatch: isLastBatch }];
}

const costs = Array.isArray(rawData) ? rawData : Object.values(rawData);

function parseTime(timeStr) {
  if (!timeStr) return 0;
  const parts = timeStr.split(':');
  if (parts.length === 2) {
    const hours = parseInt(parts[0]) || 0;
    const minutes = parseInt(parts[1]) || 0;
    return Math.round((hours + (minutes / 60)) * 100) / 100;
  }
  return 0;
}

const results = [];
for (const cost of costs) {
  const taskId = cost.task?.id ? Number(cost.task.id) : null;
  if (!taskId || !validTaskIds.has(taskId)) continue;

  const wsUserId = cost.user_from?.id ? Number(cost.user_from.id) : null;
  const finalUserId = (wsUserId && validUserIds.has(wsUserId)) ? wsUserId : 7;

  results.push({
    id: Number(cost.id),
    task_id: taskId,
    user_id: finalUserId,
    time_str: cost.time || null,
    hours: parseTime(cost.time),
    money: cost.money ? parseFloat(cost.money) : null,
    comment: cost.comment || null,
    date_log: cost.date || null,
    _nextOffset: nextOffset,
    _isLastBatch: isLastBatch
  });
}

if (results.length === 0) {
  return [{ _empty: true, _projectId: projectId, _nextOffset: nextOffset, _isLastBatch: isLastBatch }];
}
return results;

